import{_ as e,c as l,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"火山旅","description":"周易折中 - 火山旅","frontmatter":{"title":"火山旅","description":"周易折中 - 火山旅"},"headers":[],"relativePath":"zh/classics/zhezhong/062.md","filePath":"zh/classics/zhezhong/062.md"}'),h={name:"zh/classics/zhezhong/062.md"};function n(d,a,p,t,s,o){return r(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="火山旅" tabindex="-1">火山旅 <a class="header-anchor" href="#火山旅" aria-label="Permalink to “火山旅”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈旅序卦〉：“《丰》大也，穷大者必失其居，故受之以《旅》。《丰》盛，至于穷极，则必失其所安，《旅》所以次《丰》也。为卦离上艮下，山止而不迁，火行而不居，违去而不处之象，故为《旅》也。又丽乎外，亦《旅》之象。”</p><p>旅：小亨，旅贞吉</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>旅，羁旅也。山止于下，火炎于上，为去其所止而不处之象，故为旅。以六五得中于外而顺乎上下之二阳，艮止而离丽于明，故其占可以小亨。而能守其旅之贞，则吉。旅非常居，若可苟者，然道无不在，故自有其正，不可须臾离也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>以卦才言也。如卦之才可以小亨，得旅之贞正而吉也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰 ：在旅而亨，亨之小者也。然事有小大，道无不在。大亨固利于贞，不可以亨之小而失其贞也。正道果可须臾离哉？</li></ul><p>象曰：山上有火，旅。君子以明慎用刑而不留狱</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>愼刑如山，不留如火。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>火之在高，明无不照。君子观明照之象，则以明慎用刑。明不可恃，故戒于慎。明而止亦慎，象观火行不处之象，则不留狱。狱者不得已而设，民有罪而入，岂可留滞淹久也？</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰 ：火在山上，逐草而行，势不久留，故为旅象。又上下二体，艮止离明，故君子象此以明察审慎用刑，而不稽留狱讼。</p></li><li><p>项氏安世曰 ：山非火之所留也，野烧延缘过之而已，故名之曰旅，而象之以不留狱。</p></li><li><p>赵氏汝梅曰 ：火炀则宅于灶，冶则宅于炉，在山则野烧之暂，犹旅寓耳，故为旅之象。离虚为明，艮止为谨，君子体之明谨于用刑而不留狱。盖狱者人之所旅也，不留狱不使久处其中也。用刑固贵于明，然明者未必谨，谨者或留狱。明矣谨矣而淹延不决，虽明犹暗也，虽谨反害也。</p></li><li><p>张氏淸子曰 ：明则无遁情，慎则无滥罚。明慎既尽，断决随之。圣人取象于旅，正恐其留狱也。</p></li></ul><p>彖曰：旅，小亨；柔得中乎外而顺乎刚，止而丽乎明，是以小亨。旅贞吉也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦体、卦德释卦辞</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>六上居五，柔得中乎外也；丽乎上下之刚，顺乎刚也；下艮止，上离丽，止而丽于明也。柔顺而得在外之中，所止能丽于明，是以小亨，得旅之贞正而吉也。旅困之时，非阳刚中正有助于下，不能致大亨也。所谓“得在外之中”，中非一揆，旅有旅之中也。止丽于明，则不失时宜，然后得处旅之道。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏宗传曰 ：用刚非旅道也，故莫尚乎用柔。然柔不可过也，故莫尚乎得中。以六居五，得中位而属外体，丽乎二刚之间，故曰“柔得中乎外而顺乎刚”。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>处旅之道，审几度势，贵于明也。待人接物，亦贵于明也。然明不可以独用，故必以止静为本，而明丽焉。与晋、睽之主于顺说者同。</p><p>旅之时义大矣哉</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>旅之时为难处</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>天下之事，当随时各适其宜，而旅为难处，故称其时义之大。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>俞氏琰曰 ：旅之时最难处，旅之义不可不知。葢其亨虽小，其时义则大。圣人小其亨而大其时义，非大旅也，大其处旅之道也。</p></li><li><p>钱氏一本曰 ：难处者，旅之时；难尽者，旅之义。或以旅兴，或以旅䘮，所闗甚大。</p></li></ul><p>初六：旅琐琐，斯其所取灾</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>当旅之时，以阴柔居下位，故其象占如此。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>六以阴柔在旅之时，处于卑下，是柔弱之人处旅困而在卑贱，所存污下者也。志卑之人既处旅困，鄙猥琐细，无所不至，乃其所以致侮辱取灾咎也。琐琐，猥细之状。当旅困之时，才质如是，上虽有援，无能为也。四阳性而离体，亦非就下者也。又在旅与他卦为大臣之位者异矣。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏应麟曰 ：《旅》初六“所其所取灾”，王辅嗣注云，为斯贱之役，唐郭京谓“斯”合作“㒋”。愚按后汉左雄传“职斯禄薄”，注云：“斯，贱也”。 不必改“㒋”字。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>易中初爻多取童稚小子之象，在旅则童仆之象，王氏之说是也。</p><p>象曰：旅琐琐，志穷灾也</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>志意穷迫，益自取灾也。灾眚对言，则有分；独言则谓灾患耳。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>谷氏家杰曰 ：爻贱其行，象鄙其志。</p></li><li><p>杨氏启新曰 ：穷不是困穷局促猥陋之义，而是指志向的穷尽和失落，由此导致的灾难。</p></li></ul><p>六二：旅即次，怀其资，得童仆贞</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>即次则安，怀资则裕，得其童仆之贞信则无欺而有赖。旅之最吉者也。二有柔顺中正之德，故其象占如此。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>二有柔顺中正之德。柔顺则众与之，中正则处不失当，故能保其所有。童仆亦尽其忠信，虽不若五有文明之德、上下之助，亦处旅之善者也。次舎，旅所安也；财货，旅所资也；童仆，旅所赖也。得就次舎，怀蓄其资财，又得童仆之贞良，旅之善也。柔弱在下者，童也；强壮处外者，仆也。二柔顺中正，故得内外之心。在旅所亲比者，童仆也。不云吉者，旅寓之际，得免于灾厉则已善矣。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏炳文曰 ：旅中不能无赖乎童仆之用，亦多不免乎童仆之欺。惟得其贞信者，则无欺而有赖。</p></li><li><p>赵氏玉泉曰 ：二处旅而有柔顺中正之德，则内不失己而已无不安，外不失人而人无不与。几旅之所恃以不可无者，皆有以全之也。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>二得位得中，故曰“即次怀资”，与九四之“旅处而得其资斧”者异矣。下有初六比之，故曰“得童仆”，与九三之“丧其童仆”者异矣。在初则为童仆之琐琐者，自二视之，则为童仆之贞者，义不相害也。</p><p>象曰：得童仆贞，终无尤也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>羁旅之人所赖者童仆也，既得童仆之忠贞，终无尤悔矣。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏弼曰 ：既得童仆，然后即次怀资，皆无所失，故终无尤。</li></ul><p>九三：旅焚其次，丧其童仆贞，厉</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>过刚不中，居下之上，故其象占如此。丧其童仆，则不止于失其心矣，故“贞”字连下句为义。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>处旅之道，以柔顺谦下为先。三刚而不中，又居下体之上，与艮之上有自高之象。在旅而过刚自高，致困灾之道也。自高则不顺于上，故上不与而焚其次，失所安也。上离为焚象，过刚则暴下，故下离而丧其童仆之贞信，谓失其心也。如此，则危厉之道也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>潘氏梦旗曰 ：居刚而用刚，平时犹不可，况旅乎？以此与下“焚次丧仆”，固其宜也。九三以刚居下体之上，则焚次；上九以刚居上体之上，则焚巢。位愈高，刚愈亢，则祸愈深矣。</p></li><li><p>丘氏富国曰 ：九三爻辞全与二反。二即次而三焚，二得童仆而三丧。二之贞无尤，而三之贞则厉者，二柔顺得中，三过刚不中故也。过刚岂处旅之道哉？</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>三得位，故亦有即次之象，以其过刚，故焚之也。六爻惟二三言次，得位故也。</p><p>象曰：旅焚其次，亦以伤矣；以旅与下，其义丧也</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>以旅之时而与下之道如此，义当丧也。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>旅焚失其次舍，亦以困伤矣。以旅之时而与下之道如此，义当丧也。在旅而以过刚自高待下，必丧其忠贞，谓失其心也。在旅而失其童仆之心，为可危也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郭氏雍曰 ：九三刚而不中，故不能安旅，失其所安亦可伤矣。以刚暴之才而以旅道居童仆，宜其失众心而丧也。夫旅岂与人之道哉？君子自厚而已，故终无以旅与下之事。</p></li><li><p>王氏宗传曰 ：既已有焚其次之伤矣，而又丧其童仆焉，此暴厉之过也。夫旅亲寡之时也，朝夕之所与者童仆而已尔，岂可以旅视之也？九三以旅视乎下，则彼童仆也，亦必以旅视乎上矣，其能久留乎？故曰其义丧也。</p></li><li><p>黄氏淳耀曰 ：下即童仆，以旅与下者，谓视童仆如旅人也。焚次而失其身所依庇，亦已伤而不安矣，况又丧其童仆乎？然非童仆之无良也，当旅时而与下之道刻薄寡恩，直若旅人然，宜不得其心力，义当丧也，将谁咎哉？</p></li></ul><p>九四：旅于处，得其资斧，我心不快</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>以阳居阴，处上之下，用柔能下，故其象占如此。然非其正位，又上无刚阳之与，下唯阴柔之应，故其心有所不快也。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>四阳刚虽不居中，而处柔在上体之下，有用柔能下之象，得旅之宜也。以刚明之才，为五所与，为初所应，在旅之善者也。然四非正位，故虽得其处止，不若二之就次舎也。有刚明之才，为上下所与，乃旅而得货财之资、器用之利也。虽在旅为善，然上无刚阳之与，下唯阴柔之应，故不能伸其才、行其志，其心不快也。云“我”者，据四而言。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><p>蒋氏悌生曰：凡卦爻，阳刚皆胜阴柔，惟旅卦不然。二五皆以柔顺得吉，三上皆以阳刚致凶。六爻中，六五最善，二次之，上九最凶，三再次之。九四虽得其处，姑足以安其身而已，岂得尽遂其志？</p><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>四居位非正，故不曰“即次”而曰“于处”。在旅而处多惧之地，故虽得资（与六二同），而未免加斧以自防卫。其未忘戒心可知，安得快然而安乐乎？</p><p>象曰：旅于处，未得位也；得其资斧，心未快也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>四以近君为当位，在旅五不取君义，故四为未得位也。然则以九居四，不正为有咎矣。曰以刚居柔，旅之宜也。九以刚明之才，欲得时而行其志，故虽得资斧于旅为善，其心志未快也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>黄氏淳耀曰 ：资斧，防患之物，得其资斧不过有以自防，故曰心未快也。</li></ul><p>六五：射雉一矢亡，终以誉命</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>雉，文明之物，离之象也。六五柔顺文明，又得中道，为离之主，故得此爻者为射雉之象。虽不无亡矢之费，而所丧不多，终有誉命也。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>六五有文明柔顺之德，处得中道而上下与之，处旅之至善者也。人之处旅，能合文明之道，可谓善矣。羁旅之人，动而或失，则困辱随之；动而无失，然后为善。离为雉，文明之物。射雉，谓取则于文明之道而必合，如射雉一矢而亡之，无不中，则终能致誉命也。誉，令闻也；命，福禄也。五居文明之位，有文明之德，故动必中文明之道也。五君位，人君无旅，旅则失位，故不取君义。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱氏震曰 ：五在旅卦不取君象，有文明之德，则令誉升闻而爵命之矣。</p></li><li><p>朱子语类云 ：亡字正如秦无亡矢遗镞之“亡”，不是如伊川之说。易中凡言“终吉”者，皆是初不甚好也。</p></li><li><p>王氏申子曰 ：一矢亡，言中之易也。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>五在旅卦不取君义，程传之说是也。古者士大夫出疆则以贽行，而士执雉以相见。射雉而得，是进身而有阶之象也。信于友则有誉，获乎上则有命。</p><p>象曰：终以誉命，上逮也</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>上逮言其誉命闻于上也。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>有文明柔顺之德，则上下与之逮与能。顺承于上，而上与之，为上所逮也。在上而得乎下，为下所上逮也。在旅而上下与之，所以致誉命也。旅者困而未得所安之时也，终以誉命，终当致誉命也。己誉命则非旅也，困而亲寡则为旅，不必在外也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏瑗曰 ：六五所谓柔得中乎外而顺乎刚者也，柔顺中正之德为上九所信，尊显之命及之也。</li></ul><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>六五有位而上九无位，不必以六五为上九所尊显也。盖居高位便是上逮尔，此爻虽不以君位言，而亦主于大夫士之载䞇而获乎名位者，故曰上逮，言其地望已高也。</p><p>上九：鸟焚其巢，旅人先笑后号啕，丧牛于易，凶</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>上九过刚，处旅之上，离之极，骄而不顺，凶之道也。故其象占如此。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>鸟，飞腾处高者也。上九刚不中而处最高，又离体，其亢可知，故取鸟象。在旅之时，谦降柔和乃可自保，而过刚自高，失其所安，宜矣。巢，鸟所安止，焚其巢，失其所安，无所止也。在离上为焚象。阳刚自处于至高，始快其意，故先笑；既而失安莫与，故号啕。轻易以丧其顺德，所以凶也。牛，顺物。丧牛于易，谓忽易以失其顺也。离火性上为躁易之象。上承“鸟焚其巢”，故更加“旅人”字。不云“旅人”，则是鸟笑哭也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏宗传曰 ：上九之视九三尤为刚亢者也。凡物栖高处亢而寄诸危地者，鸟之巢是也。故旅之上取以为象。夫高极必危，离火有焚象也，故曰“鸟焚其巢”。先笑谓喜居物上也，后号啕谓巢焚之故也。夫牛，顺物也。旅道以柔顺谦下为本，上九丧其至顺之德，此所以凶也。</p></li><li><p>徐氏几曰 ：旅贵柔顺中正，三阳爻皆失之，而最亢者上九也。</p></li></ul><p>象曰：以旅在上，其义焚也；丧牛于易，终莫之闻也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>以旅在上而以尊高自处，岂能保其居？其义当有焚巢之事。方以极刚自高为得志而笑，不知丧其顺德于躁易，是终莫之闻，谓终不自闻知也。使自觉知，则不至于极而号啕矣。阳刚不中而处极，固有高亢躁动之象，而火复炎上，则又甚焉。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li>张子曰 ：以阳极上旅而骄肆者也，失柔顺之正，故曰丧牛于易。怒而忤物，虽有凶危，其谁告之？故曰终莫之闻也。</li></ul><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>九三以旅与下，郭氏、王氏、黄氏之说美矣。惟以旅在上，则未有说。盖以旅之道在上，则视所居之位如寄寓然，其无敬畏之心可知，故曰其义焚也。</p><h3 id="总论" tabindex="-1">总论 <a class="header-anchor" href="#总论" aria-label="Permalink to “总论”">​</a></h3><ul><li>范氏仲淹曰：内止而不动于心，外明而弗迷其往，以斯适旅，故得小亨而贞吉。夫旅人之志，卑则自辱，高则见疾，能执其中，可谓智矣。故初琐琐，卑以自辱者也；三焚次而上焚巢，高而见疾者也；二怀资而五誉命，柔而不失其中者也。</li></ul>',125)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
